sys_variable_value.value:
(function execute(inputs, outputs) {
    var valorBRL = inputs.Value_brl;

    var apiKey = "fca_live_2NujlK7dKpAXFRfOCbxYQKl3eut4yWXcHLZAkcF6";

    var url = "https://api.freecurrencyapi.com/v1/latest?apikey=" + apiKey + "&currencies=USD&base_currency=BRL";

    var r = new sn_ws.RESTMessageV2();
    r.setEndpoint(url);
    r.setHttpMethod("GET");

    var response = r.execute();
    var parsed = JSON.parse(response.getBody());

    var taxa = parsed.data.USD;

    
    outputs.Value_usd = parseFloat((valorBRL * taxa).toFixed(2));
})(inputs, outputs);

